#include "mesh.h"#include "FileStuff.h"#include "BMP.h"OSErr putBounce ( FSSpec &theMeshFSSpec );OSErr putBounce ( FSSpec &theMeshFSSpec ){//----------------------------------vars--------------------------------------------------	short		theMeshFileRef;	OSErr		theError;	char *theMap;	int i, x, y;	long theWidth, theHeight, theSize;	struct meshHeader theMeshHeader;	struct gridData *theGrid;//----------------------------------------------------------------------------------------		theError = FSpOpenDF ( &theMeshFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr )		return theError;	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	theWidth = theMeshHeader.meshWidth * 16;	theHeight = theMeshHeader.meshHeight * 16;	theSize =  theWidth * theHeight;	theGrid = (struct gridData *) NewPtr (theSize * sizeof(gridData));	if ( theGrid == nil ){		FSClose ( theMeshFileRef );		return -1;	}	FileRead(theGrid, theMeshHeader.meshLength, theMeshFileRef);	theMap = (char *) NewPtr ( theSize );	if ( theMap == nil ){		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return -1;	}	theError = readBMP ( "\p:Graphics.in:bounce.bmp", theWidth, theHeight, nil, theMap );	if ( theError != noErr ){		DisposePtr ( (Ptr) theMap );		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return theError;	}		for ( y = 0, i = 0; y < theHeight * theWidth; y += theWidth )		for ( x = theWidth - 1; x >= 0; x--, i++ )				theGrid[i].bounce = theMap[x + y];	FileSeek ( theMeshFileRef, 1088L );	FileWrite (theGrid, theMeshHeader.meshLength, theMeshFileRef);	DisposePtr ( (Ptr) theMap );	DisposePtr ( (Ptr) theGrid );	FSClose ( theMeshFileRef );	return	noErr;}